const b = $input.first().json.body ?? $input.first().json;
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const str = (v, n = 200) => String(v ?? '').trim().slice(0, n);
const safeLink = (v) => (/^https?:\/\/\S+$/i.test(str(v, 800)) ? str(v, 800) : '');
const isEmail = (e) => e.length > 0 && e.length <= 254 && /^[^\s@<>(),;:"\\]+@[^\s@<>(),;:"\\]+\.[^\s@<>(),;:"\\]{2,}$/.test(e);

const email = str(b.email, 254);
const dest = str(b.destination, 100) || 'điểm đến bạn quan tâm';
const name = str(b.name, 120) || 'bạn';
const tour = str(b.selected_tour_name, 160);
const optOut = safeLink(b.opt_out_url);

// Mở đầu theo nhóm khách (customer_segment). Không có nhóm thì dùng mặc định.
const openers = {
  family: 'Chuyến đi gia đình cần lịch trình nhẹ nhàng, nhiều điểm dừng thoải mái.',
  budget: 'Chúng tôi chọn các lựa chọn tối ưu chi phí nhưng vẫn đủ trải nghiệm.',
  resort: 'Với mong muốn nghỉ dưỡng, các gợi ý dưới đây tập trung vào lưu trú và thư giãn.',
  explorer: 'Với tinh thần khám phá, các gợi ý dưới đây có nhiều hoạt động ngoài trời.',
  general: 'Dưới đây là vài gợi ý để bạn tham khảo.',
};
const opener = openers[str(b.customer_segment, 40)] || openers.general;

const copy = {
  itinerary_delivery: { subject: `Lịch trình ${dest} của bạn từ VietJourney`,
    body: 'Đây là lịch trình tham khảo bạn đã yêu cầu. Giá trong lịch trình chỉ mang tính mô phỏng, chưa phải báo giá chính thức.' },
  tour_suggestions: { subject: `VietJourney - Gợi ý tour ${dest}`,
    body: `Chúng tôi đã chọn sẵn vài lựa chọn cho chuyến đi ${dest}.` + (tour ? ` Bạn đã từng quan tâm tới: ${tour}.` : '') },
  destination_guide: { subject: `Có gì đáng đi ở ${dest}?`,
    body: `Những điểm nổi bật và thời điểm đẹp nhất để đi ${dest}, để bạn cân nhắc lịch trình.` },
  trip_checklist: { subject: `Chuẩn bị cho chuyến đi ${dest}`,
    body: 'Danh sách việc nên chuẩn bị trước chuyến đi: giấy tờ, thời tiết, trang phục, thuốc cá nhân.' },
  intent_check: { subject: `Bạn còn dự định đi ${dest} không?`,
    body: 'Nếu bạn vẫn muốn đi, chỉ cần trả lời email này, chúng tôi sẽ hỗ trợ ngay.' },
  close_file: { subject: 'VietJourney - Hẹn gặp lại khi bạn sẵn sàng',
    body: 'Chúng tôi sẽ không gửi thêm email nuôi dưỡng. Khi bạn cần, hãy quay lại bất cứ lúc nào.' },
};
const action = str(b.action, 40);
const item = copy[action];

// Không gửi nếu thiếu email hợp lệ, action lạ, hoặc thiếu link hủy nhận (bắt buộc theo quy định).
let reason = '';
if (!isEmail(email)) reason = 'missing_or_invalid_email';
else if (!item) reason = 'unknown_action';
else if (!optOut) reason = 'missing_opt_out_url';

const html = reason ? '' :
  '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#222;max-width:640px">' +
  `<h2 style="margin:0 0 10px">Xin chào ${esc(name)},</h2>` +
  `<p style="margin:0 0 12px">${esc(opener)}</p>` +
  `<p style="margin:0 0 12px">${esc(item.body)}</p>` +
  (action === 'itinerary_delivery' && str(b.plan_summary, 2000) ? `<pre style="white-space:pre-wrap;background:#f7f4ee;padding:12px;border-radius:8px">${esc(str(b.plan_summary, 2000))}</pre>` : '') +
  '<p style="margin:24px 0 0;font-size:12px;color:#777">Bạn không muốn nhận email nuôi dưỡng? ' +
  `<a href="${esc(optOut)}">Hủy nhận email</a>.</p>` +
  '<p style="margin:16px 0 0">Trân trọng,<br><b>VietJourney Tours</b></p></div>';

return [{ json: {
  lead_id: str(b.lead_id, 80),
  email_to: reason ? '' : email,
  email_subject: reason ? '' : item.subject,
  email_html: html,
  skip_reason: reason,
} }];
